interface CityCoord {
  x: number;
  y: number;
  stateId: string;
  labelDx: number;
  labelDy: number;
  anchor: 'start' | 'middle' | 'end';
}

const CITY_COORDINATES: Record<string, CityCoord> = {
  Bangalore: { x: 345, y: 790, stateId: 'INKA', labelDx: -6, labelDy: 16, anchor: 'middle' },
  Hyderabad: { x: 412, y: 648, stateId: 'INTG', labelDx: 0, labelDy: -12, anchor: 'middle' },
  Chennai: { x: 424, y: 782, stateId: 'INTN', labelDx: 12, labelDy: 4, anchor: 'start' },
  Pune: { x: 275, y: 625, stateId: 'INMH', labelDx: 0, labelDy: -12, anchor: 'middle' },
};

const STATE_TO_CITY: Record<string, string> = {
  INKA: 'Bangalore',
  INTG: 'Hyderabad',
  INTN: 'Chennai',
  INMH: 'Pune',
};

export const IndiaDeliveryMap: React.FC<IndiaDeliveryMapProps> = ({
  locations,
  hoveredLocation,
  onHoverLocation,
  onSelectLocation,
}) => {
  const [zoomMode, setZoomMode] = React.useState<'focus' | 'all'>('focus');
  const isFocus = zoomMode === 'focus';
  const viewBox = isFocus ? '150 480 340 450' : '70 20 860 960';

  const locMap = React.useMemo(() => {
    const m = new Map<string, HubLocation>();
    locations.forEach((l) => m.set(l.location.toLowerCase(), l));
    return m;
  }, [locations]);

  // Find active hub data for floating tooltip
  const activeLocData = hoveredLocation
    ? locMap.get(hoveredLocation.toLowerCase()) || null
    : null;
  const activeCoord = hoveredLocation ? CITY_COORDINATES[hoveredLocation] : null;

  return (
    <div className="relative w-full h-full flex items-center justify-center select-none overflow-hidden group">
      {/* Zoom Mode Micro Switcher */}
      <div className="absolute top-1 right-1 flex items-center bg-slate-100/90 dark:bg-slate-800/90 backdrop-blur-xs p-0.5 rounded-md border border-slate-200/80 dark:border-slate-700/80 shadow-2xs z-10 text-[9px]">
        <button
          type="button"
          onClick={() => setZoomMode('focus')}
          className={`px-1.5 py-0.5 rounded font-semibold transition-all cursor-pointer ${
            zoomMode === 'focus'
              ? 'bg-white dark:bg-slate-900 text-cyan-600 dark:text-cyan-400 font-bold shadow-2xs'
              : 'text-slate-500 dark:text-slate-400 hover:text-slate-800 dark:hover:text-slate-200'
          }`}
          title="Focus on delivery hub corridor"
        >
          Corridor
        </button>
        <button
          type="button"
          onClick={() => setZoomMode('all')}
          className={`px-1.5 py-0.5 rounded font-semibold transition-all cursor-pointer ${
            zoomMode === 'all'
              ? 'bg-white dark:bg-slate-900 text-cyan-600 dark:text-cyan-400 font-bold shadow-2xs'
              : 'text-slate-500 dark:text-slate-400 hover:text-slate-800 dark:hover:text-slate-200'
          }`}
          title="Show full India country outline"
        >
          All India
        </button>
      </div>

      <svg
        viewBox={viewBox}
        className="w-full h-full max-h-[165px] transition-all duration-300"
        preserveAspectRatio="xMidYMid meet"
      >
        {/* State Boundaries */}
        <g id="india-states">
          {INDIA_STATES.map((st) => {
            const cityName = STATE_TO_CITY[st.id];
            const cityData = cityName ? locMap.get(cityName.toLowerCase()) : null;
            const isCityActive = !!cityData;
            const isHovered =
              hoveredLocation &&
              cityName &&
              hoveredLocation.toLowerCase() === cityName.toLowerCase();

            return (
              <path
                key={st.id}
                d={st.d}
                id={st.id}
                className="transition-all duration-200 cursor-pointer"
                style={{
                  fill: isHovered
                    ? cityData?.color + '55'
                    : isCityActive
                    ? cityData?.color + '25'
                    : 'var(--map-land, rgba(148, 163, 184, 0.12))',
                  stroke: isHovered
                    ? cityData?.color
                    : isCityActive
                    ? cityData?.color + 'aa'
                    : 'var(--map-stroke, rgba(148, 163, 184, 0.35))',
                  strokeWidth: isHovered ? 2.5 : isCityActive ? 1.4 : 0.6,
                }}
                onMouseEnter={() => cityName && onHoverLocation(cityName)}
                onMouseLeave={() => onHoverLocation(null)}
                onClick={() => cityName && onSelectLocation(cityName)}
              />
            );
          })}
        </g>

        {/* Delivery Hub Markers */}
        <g id="hub-markers">
          {locations.map((loc) => {
            const coord = CITY_COORDINATES[loc.location];
            if (!coord) return null;

            const isHovered =
              hoveredLocation &&
              hoveredLocation.toLowerCase() === loc.location.toLowerCase();
            const radius = isFocus
              ? Math.max(7, Math.min(14, 6 + (loc.percentage / 100) * 11))
              : Math.max(10, Math.min(22, 8 + (loc.percentage / 100) * 18));
            const labelScale = isFocus ? 1 : 1.6;

            return (
              <g
                key={loc.location}
                transform={`translate(${coord.x}, ${coord.y})`}
                className="cursor-pointer transition-transform duration-200"
                onMouseEnter={() => onHoverLocation(loc.location)}
                onMouseLeave={() => onHoverLocation(null)}
                onClick={() => onSelectLocation(loc.location)}
              >
                {/* Radar Ripple Animation */}
                <circle
                  r={radius * 1.8}
                  fill={loc.color}
                  opacity={isHovered ? 0.45 : 0.2}
                >
                  <animate
                    attributeName="r"
                    values={`${radius};${radius * 2.2}`}
                    dur="2s"
                    repeatCount="indefinite"
                  />
                  <animate
                    attributeName="opacity"
                    values="0.45;0"
                    dur="2s"
                    repeatCount="indefinite"
                  />
                </circle>

                {/* Secondary Pulse Ring */}
                <circle
                  r={radius}
                  fill={loc.color}
                  opacity={isHovered ? 0.35 : 0.15}
                />

                {/* Core Beacon Dot */}
                <circle
                  r={isHovered ? radius * 0.48 : radius * 0.4}
                  fill={loc.color}
                  stroke="#ffffff"
                  strokeWidth={isHovered ? 2.5 : 1.8}
                  className="transition-all duration-150 drop-shadow-sm"
                />

                {/* Micro City Label with Contrast Halo */}
                <text
                  x={coord.labelDx * labelScale}
                  y={coord.labelDy * labelScale}
                  textAnchor={coord.anchor}
                  className={`font-extrabold tracking-tight select-none pointer-events-none transition-all stroke-white/95 dark:stroke-slate-900/95 ${
                    isHovered
                      ? 'fill-slate-900 dark:fill-white font-black'
                      : 'fill-slate-800 dark:fill-slate-100'
                  }`}
                  style={{
                    fontSize: isFocus ? (isHovered ? '16px' : '14px') : (isHovered ? '24px' : '20px'),
                    strokeWidth: isFocus ? 3.5 : 5,
                    paintOrder: 'stroke fill',
                  }}
                >
                  {loc.location}
                </text>
              </g>
            );
          })}
        </g>
      </svg>

      {/* Floating Interactive Badge overlay on Hover */}
      {activeLocData && activeCoord && (
        <div className="absolute bottom-1 left-2 bg-slate-900/90 dark:bg-slate-800/95 text-white backdrop-blur-md px-2.5 py-1 rounded-lg border border-slate-700/80 shadow-lg text-[10px] flex items-center gap-2 pointer-events-none animate-in fade-in zoom-in-95 duration-150 z-20">
          <span
            className="w-2 h-2 rounded-full shrink-0"
            style={{ backgroundColor: activeLocData.color }}
          />
          <span className="font-bold">{activeLocData.location}</span>
          <span className="text-slate-300 font-mono">
            {activeLocData.count} staff ({activeLocData.percentage}%)
          </span>
        </div>
      )}
    </div>
  );
};
